\label{geo-square}
For $\Omega=\widetilde\omega I-F_D$,
\[
 \frac{\Omega^2}{\widetilde\omega^2}
 =\operatorname{diag}(\mathcal A_0+i\mathcal B_0,
                       \mathcal A_1+i\mathcal B_1,
                       \mathcal A_2+i\mathcal B_2),
\]
where
\begin{equation}\label{geo-AB}
 \mathcal A_j=I-\tfrac12(H_jS_j+S_jH_j)+K_j,\qquad
 \mathcal B_j=H_j+S_j.
\end{equation}

\label{geo-torsion}
Every coefficient pair belongs to $\mathcal T_{\mathcal D_K}$, including
all nonsaturated and mixed coherent quotients.

\label{geo-elementary-exclusions}
There is no smooth strictly calibrated solution if
$\operatorname{rank}A\le1$ or $B=0$, including their intersections.

\label{geo-euler-exclusion}
No original pair in the stratum $(2,2,0)$ admits a smooth strictly
calibrated solution.

\label{common-mass-inverse}
For each fixed reference and \(0<\gamma<1\) there are finite
\(t_0,C_I\), independent of \(t\ge t_0\), for which
\(L_t=J_*+tA_*\) is an unrestricted isomorphism and
\begin{equation}\label{common-weighted-inverse}
 N_t(U):=t\|U\|_\gamma+\sqrt t\|DU\|_\gamma+\|D^2U\|_\gamma
 \le C_I\|L_tU\|_\gamma.
\end{equation}
Here and below \(\|\cdot\|_\gamma=\|\cdot\|_{C^{0,\gamma}}\) in a fixed
finite precompact atlas and the fixed flat real fiber frame.
